    "formula": {
     "sq": "Kërkesat e mbyllura brenda afatit (ditët nga regjistrimi te mbyllja ≤ afati në ditë) ÷ të gjitha kërkesat e mbyllura në periudhë × 100.",
     "en": "Requests closed within their deadline (days from registration to closing ≤ deadline in days) ÷ all requests closed in the period × 100."
    },
    "question": {
     "sq": "Sa përqind e kërkesave zgjidhen brenda afatit?",
     "en": "What share of requests is resolved within the deadline?"
    },
    "sql": "WITH w AS (\n  SELECT date_trunc('year', max(created_at))::DATE AS y0, last_day(max(created_at)) AS m1\n  FROM request\n), c AS (\n  SELECT r.created_at, r.closed_at, r.sla_days\n  FROM request r, w\n  WHERE r.closed_at BETWEEN w.y0 AND w.m1 AND r.sla_days IS NOT NULL\n)\nSELECT\n  100.0 * count(*) FILTER (WHERE datediff('day', c.created_at, c.closed_at) <= c.sla_days)\n    / nullif(count(*), 0) AS value,\n  (SELECT strftime(m1, '%Y-%m') FROM w) AS period\nFROM c",
