    "formula": {
     "sq": "Shpenzimet faktike ÷ shpenzimet e planifikuara të periudhës (të gjitha programet, korrente dhe kapitale, janar – muaji i fundit) × 100.",
     "en": "Actual spending ÷ planned spending for the period (all programmes, current and capital, January to the latest month) × 100."
    },
    "question": {
     "sq": "Sa është zbatuar buxheti deri tani?",
     "en": "How much of the budget has been executed so far?"
    },
    "sql": "WITH w AS (\n  SELECT date_trunc('year', max(month))::DATE AS y0, max(month) AS m FROM budget_line\n)\nSELECT\n  100.0 * (SELECT sum(b.actual_lek) FROM budget_line b WHERE b.month BETWEEN w.y0 AND w.m)\n    / nullif((SELECT sum(b.planned_lek) FROM budget_line b WHERE b.month BETWEEN w.y0 AND w.m), 0)\n    AS value,\n  strftime(w.m, '%Y-%m') AS period\nFROM w",
