    "question": {
     "sq": "Sa kërkesa të hapura e kanë kaluar afatin?",
     "en": "How many open requests are past their deadline?"
    },
    "sql": "WITH w AS (SELECT last_day(max(created_at)) AS asof FROM request)\nSELECT\n  (SELECT count(*) FROM request r\n   WHERE r.created_at <= w.asof\n     AND (r.closed_at IS NULL OR r.closed_at > w.asof)\n     AND r.sla_days IS NOT NULL\n     AND datediff('day', r.created_at, w.asof) > r.sla_days\n     AND coalesce(lower(strip_accents(r.status)), '') NOT LIKE '%refuz%')::DOUBLE AS value,\n  strftime(w.asof, '%Y-%m') AS period\nFROM w",
