    "formula": {
     "sq": "Tonët e grumbulluar × 1.000 ÷ banorët (sipas bazës së zgjedhur të popullsisë), të përvitësuar: × 12 ÷ numri i muajve me të dhëna.",
     "en": "Tonnes collected × 1,000 ÷ residents (pinned population basis), annualised: × 12 ÷ number of months with data."
    },
    "question": {
     "sq": "Sa kg mbetje prodhon një banor në vit?",
     "en": "How many kilograms of waste per resident per year?"
    },
    "sql": "WITH w AS (\n  SELECT date_trunc('year', max(month))::DATE AS y0, max(month) AS m FROM waste_collection\n), t AS (\n  SELECT sum(x.tonnes) AS tonnes, count(DISTINCT x.month) AS months\n  FROM waste_collection x, w\n  WHERE x.month BETWEEN w.y0 AND w.m\n), p AS (\n  SELECT sum(residents) AS residents FROM population WHERE basis = 'census_2023'\n)\nSELECT t.tonnes * 1000.0 / nullif(p.residents, 0) * 12.0 / nullif(t.months, 0) AS value,\n       (SELECT strftime(m, '%Y-%m') FROM w) AS period\nFROM t, p",
