    "sql": "WITH w AS (\n  SELECT least((SELECT max(month) FROM revenue), (SELECT max(month) FROM budget_line)) AS m\n), w2 AS (SELECT date_trunc('year', m)::DATE AS y0, m FROM w)\nSELECT\n  100.0 * (SELECT sum(r.collected_lek) FROM revenue r\n           WHERE lower(strip_accents(r.revenue_type)) LIKE '%pastrim%'\n             AND r.month BETWEEN w2.y0 AND w2.m)\n    / nullif((SELECT sum(b.actual_lek) FROM budget_line b\n              WHERE b.programme_code = '05100' AND b.month BETWEEN w2.y0 AND w2.m), 0)\n    AS value,\n  strftime(w2.m, '%Y-%m') AS period\nFROM w2",
