    "formula": {
     "sq": "Largimet gjatë vitit ÷ numri mesatar i punonjësve × 100; numri mesatar = (numri në fund + numri në fillim) ÷ 2, ku numri në fillim = numri në fund − pranimet + largimet.",
     "en": "Leavers during the year ÷ average headcount × 100; average headcount = (end headcount + start headcount) ÷ 2, where start headcount = end headcount − hires + leavers."
    },
    "question": {
     "sq": "Sa është rotacioni i punonjësve këtë vit?",
     "en": "What is the staff turnover rate this year?"
    },
    "sql": "WITH a AS (SELECT max(as_of) AS d FROM staff),\ns AS (\n  SELECT sum(st.headcount) AS hc,\n         sum(coalesce(st.hires, 0)) AS h,\n         sum(coalesce(st.leavers, 0)) AS l\n  FROM staff st, a\n  WHERE st.as_of IS NOT DISTINCT FROM a.d\n)\nSELECT 100.0 * s.l / nullif((s.hc + (s.hc - s.h + s.l)) / 2.0, 0) AS value,\n       (SELECT strftime(d, '%Y-%m') FROM a) AS period\nFROM s",
