    "unit": "kg_per_resident",
    "passport_code": "WST-02",
    "sql": "WITH w AS (\n  SELECT date_trunc('year', max(month))::DATE AS y0, max(month) AS m FROM waste_collection\n), t AS (\n  SELECT sum(x.tonnes) AS tonnes, count(DISTINCT x.month) AS months\n  FROM waste_collection x, w\n  WHERE x.month BETWEEN w.y0 AND w.m\n), p AS (\n  SELECT sum(residents) AS residents FROM population WHERE basis = $basis\n)\nSELECT t.tonnes * 1000.0 / nullif(p.residents, 0) * 12.0 / nullif(t.months, 0) AS value,\n       (SELECT strftime(m, '%Y-%m') FROM w) AS period\nFROM t, p",
